#include <item/PetStudyWire.hpp>
#include <item/EquipmentStats.hpp>
void OriginalPetBookCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,
    const std::string& password,const std::string& path,const std::vector<BulkSource>& sources)
{
    using namespace auriga::item;Check(sources.size()==13,"twelve original books and dependent chest");CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"owned original pet book SQL connection");auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-original-pet-book-worker").has_value(),"actual original pet book item worker starts");
    unsigned serial=0,packets=0,books=0,chests=0;bool replay=false;
    const auto op=[&](){++serial;return std::array<std::uint8_t,16>{0xF5,static_cast<std::uint8_t>(serial),static_cast<std::uint8_t>(serial>>8)};};
    const auto apply=[&](persistence::LoadedItemOwner& state,const ItemCommit& commit){std::optional<runtime::CommitOutcome> got;Check(runtime::RequestCommit(state.fence.owner,state.fence.sessionGeneration,commit,[&](auto out){got=std::move(out);}),"original pet book operation queued");for(unsigned spin=0;!got && spin<1000;++spin){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(got && got->write && got->state,"original pet book operation committed and reloaded");replay=got->write->replay;state=*got->state;};
    const auto relog=[&](persistence::LoadedItemOwner& state){const auto saved=state;const auto generation=persistence::ClaimOwnerSession(sql,*catalog,state.fence.owner).value();state=persistence::LoadItemOwner(sql,*catalog,state.fence.owner,generation).value();Check(state.items==saved.items && state.wallets==saved.wallets && state.petStudyCooldowns==saved.petStudyCooldowns,"book debit, pet skill, wallet and owner cooldown survive fresh SQL login");};
    const auto grant=[&](persistence::LoadedItemOwner& state,ItemGrant spec){const auto ids=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);const auto c=MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,spec,ids);Check(c.has_value(),"actual book or egg grant planned");apply(state,*c);return ids[0];};
    const auto find=[&](const auto& state,ItemInstanceId id)->const PersistentItem&{const auto found=std::ranges::find(state.items,id,&PersistentItem::id);Check(found!=state.items.end(),"owned original test item exists");return *found;};
    const auto provision=[&](std::uint64_t pid,std::uint64_t gold){const ItemOwner owner{ItemOwnerKind::Character,pid};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};const std::array wallets{ItemWallet{owner,WalletCurrency::Gold,1,gold}};Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,wallets).has_value(),"pet book owner provisioned");return persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();};
    std::optional<ItemKey> egg;const PetHatchProfile* hatch=nullptr;const PetTrainingProfile* training=nullptr;
    for(const auto& [key,entry]:catalog->Entries())if(const auto* box=std::get_if<ItemContainerRow>(&entry.category);box && box->hatchProfile && !entry.base.retired){const auto* profile=catalog->FindPetHatchProfile(*box->hatchProfile);const auto* pet=catalog->Find(profile->target);const auto* row=pet ? std::get_if<ItemCompanionRow>(&pet->category) : nullptr;const auto* t=row && row->trainingProfile ? catalog->FindPetTrainingProfile(*row->trainingProfile) : nullptr;
        if(t && row->clock==CompanionClock::ActiveTime && t->slots[3].minimumStage==0 && t->slots[3].minimumAgeMs>0){egg=key;hatch=profile;training=t;break;}}
    Check(egg && hatch && training,"real native egg and age-unlocked training slot selected");const auto now=static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count());const auto born=now-training->slots[3].minimumAgeMs-1000;
    for(unsigned n=0;n<sources.size();++n){const auto key=sources[n].grant.key;const auto* entry=catalog->Find(key);
        const auto file=[&](const std::string& phase,const char* kind,const auto& bytes){std::ofstream f(path+"."+std::to_string(n)+"."+phase+"."+kind+".hex");for(auto b:bytes){const auto v=static_cast<unsigned char>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"actual original book/chest runtime packet exported");};
        if(const auto* box=std::get_if<ItemContainerRow>(&entry->category)){++chests;auto state=provision(18100u+n,1000000);auto id=grant(state,{key});const auto write=[&](const std::string& phase){file(phase,"inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());file(phase,"details",EncodeTypedItemDetails(*catalog,state.items).value());++packets;};write("ready");const auto* loot=catalog->FindLoot(*box->lootProfile);Check(loot && loot->Data().entries.size()==14,"original box keeps twelve books and its two other real reward rows");std::uint64_t cursor=0;
            for(unsigned draw=0;draw<14;++draw){if(draw)id=grant(state,{key});const auto before=find(state,id);const auto ids=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);const auto opening=MakeContainerOpeningCommit(*catalog,op(),state.fence,state.storages,state.items,state.wallets,{id,{},{255,0,0,false},now},ids,[&](auto maximum){Check(cursor<maximum,"actual original weighted draw bound");return cursor;});Check(opening && opening->won==std::vector<std::uint16_t>{static_cast<std::uint16_t>(draw+1)},"each actual original chest row selected by its own weight interval");apply(state,opening->commit);const auto saved=state.items;apply(state,opening->commit);Check(replay && state.items==saved,"original pet chest cannot double grant on replay");relog(state);const auto phase="draw"+std::to_string(draw+1);write(phase);file(phase,"container",EncodeContainerOpening(*catalog,400,&before,nullptr,state.fence.revision,ContainerOpeningStatus::Opened,{},opening->won).value());cursor+=loot->Data().entries[draw].weight;}continue;}
        ++books;const auto* row=std::get_if<ItemPetSupplyRow>(&entry->category);const auto* supply=row ? catalog->FindPetSupplyProfile(row->profile) : nullptr;Check(supply && supply->study && supply->study->knownSuccessBp==7100 && supply->study->knownCooldownMs==10800000,"actual original study chance and owner cooldown profile");const auto skillId=supply->study->skill;const auto skill=std::ranges::find(training->skills,skillId,&PetSkillDefinition::id);Check(skill!=training->skills.end() && skill->ranks.size()==10 && skill->code.starts_with("pet.original_"),"actual original named skill has ten real ranks");
        auto state=provision(18000u+n,hatch->goldCost+1000000);const auto eggId=grant(state,{*egg});const auto book=grant(state,{key,0,13});const auto reserved=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);const auto seal=reserved[0];
        const auto actor=[&](){PetCareContext a;a.operationId=op();a.actorId=state.fence.owner.id;a.sessionGeneration=state.fence.sessionGeneration;a.rulesetRevision=1;a.characterLevel=255;a.characterClass=a.sex=1;a.admittedByServer=a.canUseItems=a.ownerAlive=true;const auto* p=catalog->FindUsePolicy(entry->base.usePolicy);while(!(p->allowedClasses&(1u<<(a.characterClass-1))))++a.characterClass;while(!(p->allowedSexes&(1u<<(a.sex-1))))++a.sex;return a;};
        const auto& eggItem=find(state,eggId);PetHatchRequest request{actor(),{eggItem.key,eggId.Value(),eggItem.revision,state.fence.owner.id,1}};request.walletRevision=state.wallets[0].revision;request.gold=state.wallets[0].balance;request.newInstanceId=seal.Value();request.bornAtUtcMs=born;request.name="Forraspet";request.recordedTraits={hatch->maximumHp.minimum,hatch->monsterDamage.minimum,hatch->pveNormalDamage.minimum};request.nameAcceptedByServer=request.newInstanceReservedByServer=true;const auto birth=MakePetHatchCommit(*catalog,state.fence,state.storages,state.items,state.wallets,request);Check(birth.has_value(),"actual original pet study subject hatches normally");apply(state,*birth);
        const auto lifecycle=[&](){const auto& p=find(state,seal);return PetLifecycleRequest{actor(),{p.key,p.id.Value(),p.revision,p.owner.id,1,0,false,false,false,true,p.growthPet->recallRequested,p.growthPet->recallRequested ? 1u : 0u},p.revision,now,*p.growthPet};};
        const auto summon=MakeGrowthPetCompanionCommit(*catalog,state.fence,state.storages,state.items,lifecycle(),CompanionAction::Summon,0);Check(summon.has_value(),"normal native summoning and measured age unlock actual training slot");apply(state,*summon);Check(find(state,seal).growthPet->skills[3].unlocked,"actual age rule unlocks fourth study slot without altering level or traits");
        const auto write=[&](const std::string& phase,unsigned status,unsigned rank,unsigned chance){const auto& p=find(state,seal);file(phase,"inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());file(phase,"details",EncodeTypedItemDetails(*catalog,state.items).value());PetStudyRuntimeView view;view.status=status;view.item=seal.Value();view.quote=(status==18 || status==22) ? 0 : 400;view.gold=state.wallets[0].balance;view.target=p.key;view.seal=&p;view.book=(status==18 || status==22) ? 0 : book.Value();view.skill=(status==18 || status==22) ? 0 : skillId;view.slot=(status==18 || status==22) ? 0 : 3;view.nextRank=rank;view.chanceBp=chance;view.readyAtMs=status==22 ? state.petStudyCooldowns.at(skillId) : 0;view.slots=p.growthPet->skills;if(status==18 && p.growthPet->skills[3].rank<10)view.options={{book.Value(),static_cast<std::uint8_t>(p.growthPet->skills[3].rank ? 24 : 8)}};if(status==22){view.seal=nullptr;view.target.reset();view.slots={};}file(phase,"study",EncodePetStudyRuntime(*catalog,view).value());auto details=view;details.withStudy=false;details.status=12;details.quote=0;details.seal=&p;details.target=p.key;file(phase,"pet",EncodePetStudyRuntime(*catalog,details).value());const auto passive=CollectPetPassiveBonuses(*catalog,lifecycle(),true,false).value();auto stats=BuildEquipmentStats(*catalog,state.fence.owner,state.items,CharacterPetBonuses(passive)).value();stats.petBonuses={seal.Value(),passive};file(phase,"stats",EncodeEquipmentStats(&stats,77,1,state.fence.revision,{}));++packets;};
        const auto study=[&](std::optional<std::uint8_t> slot,unsigned roll,std::uint64_t cooldown){return MakePetStudyCommit(*catalog,state.fence,state.storages,state.items,actor(),book,seal,{slot,now,0,cooldown,static_cast<std::uint16_t>(roll)});};
        write("ready",18,0,0);write("preview",19,1,10000);const auto selected=study(3,0,0);Check(selected && selected->plan.succeeded,"actual original selected study learns with certainty");apply(state,selected->commit);const auto saved=state.items;apply(state,selected->commit);Check(replay && state.items==saved,"original selected study receipt cannot double debit or rank");relog(state);write("learned",20,1,10000);
        const auto failed=study({},7100,0);Check(failed && !failed->plan.succeeded && (!failed->commit.petStudyCooldown || !failed->commit.petStudyCooldown->afterMs),"original29 percent failure consumes only one book and sets no owner cooldown");apply(state,failed->commit);Check(find(state,seal).growthPet->skills[3].rank==1 && state.petStudyCooldowns.empty(),"known failure preserves real rank and no persisted cooldown");write("missed",21,2,7100);
        const auto known=study({},7099,0);Check(known && known->plan.succeeded && known->commit.petStudyCooldown,"exact71 percent boundary succeeds and binds owner cooldown");apply(state,known->commit);relog(state);const auto ready=state.petStudyCooldowns.at(skillId);Check(ready==now+10800000 && !study({},0,ready),"known original book cannot bypass three-hour cooldown by relog");write("known",20,2,7100);write("cooldown",22,0,0);
        for(unsigned rank=3;rank<=10;++rank){const auto next=study(3,0,0);Check(next && next->plan.succeeded,"original explicit slot instruction remains a certain rank action");apply(state,next->commit);}Check(!study(3,0,0) && find(state,book).count==2,"maximum original rank10 refuses before another debit");const auto bonuses=CollectPetSkillBonuses(*catalog,lifecycle(),true,false).value();Check(bonuses[static_cast<unsigned>(skill->effect)]==skill->ranks[9].value,"exact original rank value reaches native passive source once");write("mastered",20,10,10000);relog(state);write("relogged",18,0,0);
    }
    Check(books==12 && chests==1 && packets==111,"all real original pet book and chest cases covered");store.Stop();std::cout<<"SOURCE_ORIGINAL_PET_BOOK_WORKER=SUCCESS sources=13 packets="<<packets<<" checks="<<checks<<std::endl;
}
